pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address oracleAddress) public {
        vm.assume(oracleAddress != address(0));
        vm.assume(oracleAddress.code.length > 0);

        // Deploy a minimal OracleProvider helper that satisfies the interface
        MockOracle oracle = new MockOracle();
        address actualOracle = address(oracle);

        // Build ProductInfo with fuzzed oracle address being the deployed mock
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "Test",
            symbol: "TST",
            payoffDefinition: PayoffDefinition(PayoffDefinitionLib.PayoffType.PASSTHROUGH, PayoffDefinitionLib.PayoffDirection.LONG, bytes30(0)),
            oracle: IOracleProvider(actualOracle),
            maintenance: UFixed18.wrap(0.1e18),
            fundingFee: UFixed18.wrap(0.01e18),
            makerFee: UFixed18.wrap(0.005e18),
            takerFee: UFixed18.wrap(0.005e18),
            positionFee: UFixed18.wrap(0.01e18),
            makerLimit: UFixed18.wrap(1000e18),
            utilizationCurve: JumpRateUtilizationCurve(
                PackedFixed18.wrap(int128(0.01e18)),
                PackedFixed18.wrap(int128(1e18)),
                PackedFixed18.wrap(int128(0.5e18)),
                PackedUFixed18.wrap(uint128(0.8e18))
            )
        });

        // The C contract must be initialized as a product by the controller (msg.sender).
        // We need to create a minimal controller to pass the initialization, or we can just prank as a contract that implements IController.
        // Here we deploy a minimal controller mock that stores the C as a product to satisfy the initializer and 'onlyProductOwner' patterns.
        MockController controller = new MockController();
        // The C constructor calls initializer(1) which calls __UControllerProvider__initialize(IController(msg.sender)).
        // So we prank as the controller's address.
        vm.prank(address(controller));
        c.initialize(info);

        // Now the oracle() getter must return the address that was passed during initialization.
        address returnedOracle = address(c.oracle());
        assertTrue(returnedOracle == actualOracle);
    }
}

contract MockOracle {
    function sync() external returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(1, block.timestamp, Fixed18.wrap(1e18));
    }
    function currentVersion() external view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(1, block.timestamp, Fixed18.wrap(1e18));
    }
    function atVersion(uint256) external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(1, block.timestamp, Fixed18.wrap(1e18));
    }
}

