// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(bytes calldata initializationData) public {
        // The initialization data is decoded into a struct mock. We must call initialize on C to set the oracle.
        // We construct minimal valid productInfo that contains an oracle address.
        // We bound the oracle address to be a contract (non-zero) via vm.assume, then pass to C.
        (
            address oracleAddr,
            string memory name,
            string memory symbol
        ) = abi.decode(initializationData, (address, string, string));

        vm.assume(oracleAddr != address(0));

        // Compose ProductInfo struct
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: name,
            symbol: symbol,
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType(0),
                payoffDirection: PayoffDefinitionLib.PayoffDirection(0),
                data: bytes30(0)
            }),
            oracle: IOracleProvider(oracleAddr),
            maintenance: UFixed18.wrap(1e18),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(type(uint256).max),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });

        // We cannot call c.initialize directly because it requires msg.sender to be IController and call initializer(1)
        // We can only test the invariant after hypothetical initialization. However, the bug is in UPayoffProvider.oracle()
        // which reads from a storage slot that is set during __UPayoffProvider__initialize.
        // Because we cannot call __UPayoffProvider__initialize without going through proper initialization,
        // we test the return value of oracle() which in the buggy version always returns address(0).
        // In the reference version, before initialization, the _oracle storage is 0 as well, so both return address(0).
        // This makes the intended invariant impossible to test via public surface without initialization.

        // But the prompt says: "Observe c ONLY through its PUBLIC/EXTERNAL surface: auto-generated getters of public state variables, public/external view/pure return values"
        // Since initialize is a public function, we can call it as long as we satisfy the modifiers.
        // We need to simulate a call from a contract that is the controller (msg.sender).
        // We deploy a minimal controller mock that satisfies only the necessary interface calls.
        // However, UPayoffProvider.__UPayoffProvider__initialize uses onlyInitializer which checks _version and _initializing.
        // We need to call c.initialize(1) from a valid Controller address.
        // We cannot deploy the full controller, but we can deploy a mock that implements the required functions.

        // Actually, __UPayoffProvider__initialize is called inside c.initialize, so if we call c.initialize from an address that passes onlyInitializer (initially, version is 0, so version 1 works) and Address.isContract(address(this) check for controller, we can initialize it.

        // But __UControllerProvider__initialize requires controller_ is a contract and stores it; then onlyProductOwner etc use controller(). This is too complex.

        // Simpler approach: the bug is in the `oracle()` function itself, which always returns address(0). We don't need to initialize to see the difference if we directly check `c.oracle()`.

        // But the reference returns 0 before initialization too; after initialization it returns the set address. The bug always returns 0.
        // We need to demonstrate a state where reference returns non-zero and bug returns 0. So we must successfully initialize.

        // We can do this by deploying a minimal controller that implements the necessary functions, then calling c.initialize from it.
        // But that would require a lot of interface implementation, which is complex.

        // We notice that `oracle()` has no modifiers; we can call it anytime. The invariant "returns original stored address" can be checked if we can set the storage slot directly?
        // No, vm.store is prohibited.

        // Given the constraints, the only way is to initialize C properly with a mock controller, then check oracle().
        // We'll include a minimal mock controller that can be faked.
        // We'll assume oracleAddr is a valid contract address that can be cast to IOracleProvider.
        // We'll deploy a mock that returns success when .sync() called.
        vm.startPrank(address(this));
        c.initialize(info);
        vm.stopPrank();

        // After initialization, oracle() must return oracleAddr.
        address actualOracle = address(c.oracle());
        assertTrue(actualOracle == oracleAddr);
    }
}

