// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();

        // Deploy a minimal IOracleProvider that returns a non-zero address to pass Address.isContract checks
        MockOracle oracle = new MockOracle();
        MockOracleProvider provider = new MockOracleProvider(oracle);

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "Test",
            symbol: "TST",
            payoffDefinition: PayoffDefinitionLib.from(0, 0, bytes30(0)),
            oracle: IOracleProvider(address(provider)),
            maintenance: UFixed18.wrap(1e18),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(1e18),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: Fixed18.wrap(0).pack(),
                maxRate: Fixed18.wrap(1e18).pack(),
                targetRate: Fixed18.wrap(1e17).pack(),
                targetUtilization: UFixed18.wrap(0.8e18).pack()
            })
        });

        vm.prank(address(this));
        c.initialize(info);
    }

    function testFuzz_property(address fuzzedNewOracle) public {
        // Ensure the fuzzed address is a contract to satisfy isContract check
        vm.assume(fuzzedNewOracle != address(0));
        vm.assume(fuzzedNewOracle.code.length > 0);

        // First, oracle() should return the original set oracle (non-zero)
        // The buggy version breaks this invariant by always returning address(0)
        assertTrue(c.oracle() != IOracleProvider(address(0)));
    }
}

contract MockOracle {
    function implementation() external view returns (address) {
        return address(this);
    }
}

contract MockOracleProvider is IOracleProvider {
    address public mockOracle;
    constructor(address oracle) {
        mockOracle = oracle;
    }
    function sync() external returns (OracleVersion memory) {}
    function currentVersion() external view returns (OracleVersion memory) {}
    function atVersion(uint256) external view returns (OracleVersion memory) {}
}

interface IProduct {
    struct ProductInfo {
        string name;
        string symbol;
        PayoffDefinition payoffDefinition;
        IOracleProvider oracle;
        UFixed18 maintenance;
        UFixed18 fundingFee;
        UFixed18 makerFee;
        UFixed18 takerFee;
        UFixed18 positionFee;
        UFixed18 makerLimit;
        JumpRateUtilizationCurve utilizationCurve;
    }
    function initialize(ProductInfo calldata) external;
    function oracle() external view returns (IOracleProvider);
    function settle() external;
    function latestVersion() external view returns (uint256);
    function pre() external view returns (PrePosition memory);
    function positionAtVersion(uint256) external view returns (Position memory);
}

struct PayoffDefinition {}
library PayoffDefinitionLib {
    function from(uint256, uint256, bytes30) internal pure returns (PayoffDefinition memory) {
        return PayoffDefinition();
    }
}

struct JumpRateUtilizationCurve {
    PackedFixed18 minRate;
    PackedFixed18 maxRate;
    PackedFixed18 targetRate;
    PackedUFixed18 targetUtilization;
}

struct PrePosition {
    uint256 oracleVersion;
    Position openPosition;
    Position closePosition;
}

struct Position {
    UFixed18 maker;
    UFixed18 taker;
}

type Fixed18 is int256;
library Fixed18Lib {
    function from(int256) internal pure returns (Fixed18) {}
    function wrap(int256) internal pure returns (Fixed18) {}
    function pack(Fixed18) internal pure returns (PackedFixed18) {}
}

type UFixed18 is uint256;
library UFixed18Lib {
    function wrap(uint256) internal pure returns (UFixed18) {}
    function pack(UFixed18) internal pure returns (PackedUFixed18) {}
}

type PackedFixed18 is int128;
type PackedUFixed18 is uint128;

interface IOracleProvider {
    struct OracleVersion {
        uint256 version;
        uint256 timestamp;
        Fixed18 price;
    }
    function sync() external returns (OracleVersion memory);
    function currentVersion() external view returns (OracleVersion memory);
    function atVersion(uint256) external view returns (OracleVersion memory);
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fuzzSeed) public {
        // 1. Admissible domain: generate a non-zero PayoffDefinition to initialize the contract.
        // The reference stores it, the mutant ignores it and returns zero; we verify the returned definition matches what was set.
        // We derive distinct non-zero fields from fuzzSeed.
        vm.assume(fuzzSeed != 0);
        PayoffDefinitionLib.PayoffType ptype = PayoffDefinitionLib.PayoffType(uint8(fuzzSeed % 3 + 1)); // 1,2,3 non-zero
        PayoffDefinitionLib.PayoffDirection pdir = PayoffDefinitionLib.PayoffDirection(uint8((fuzzSeed >> 8) % 2 + 1)); // 1,2 non-zero
        bytes30 pdata = bytes30(uint240(fuzzSeed) | (uint240(1) << 239)); // ensure non-zero bytes30
        PayoffDefinition memory def = PayoffDefinition(ptype, pdir, pdata);

        // We cannot call initialize because it's initializer(1) and only callable by the controller.
        // Instead we directly set the storage slot used by _payoffDefinition using vm.store to simulate initialization.
        // The storage slot is keccak256("equilibria.perennial.UPayoffProvider.payoffDefinition").
        bytes32 slot = keccak256("equilibria.perennial.UPayoffProvider.payoffDefinition");
        vm.store(address(c), slot, bytes32(abi.encode(def)));

        // 2. Retrieve the definition via the public getter.
        PayoffDefinition memory returned = c.payoffDefinition();

        // 3. Assert that the returned definition matches the stored one.
        // The reference satisfies this for any stored definition; the mutant returns zero regardless, thus fails for non-zero storage.
        assertTrue(
            returned.payoffType == def.payoffType &&
            returned.payoffDirection == def.payoffDirection &&
            returned.data == def.data,
            "payoffDefinition must return the stored definition"
        );
    }
}

