// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        bytes30 data,
        uint8 payoffTypeVal,
        uint8 payoffDirectionVal
    ) public {
        vm.assume(payoffTypeVal <= 2);
        vm.assume(payoffDirectionVal <= 2);
        PayoffDefinitionLib.PayoffType pType = PayoffDefinitionLib.PayoffType(payoffTypeVal);
        PayoffDefinitionLib.PayoffDirection pDir = PayoffDefinitionLib.PayoffDirection(payoffDirectionVal);
        PayoffDefinition memory expected = PayoffDefinition(pType, pDir, data);
        vm.assume(expected.valid());

        C.ProductInfo memory info;
