        bool typeOk = uint256(returned.payoffType) == uint256(initDef.payoffType);
        bool dataOk = returned.data == initDef.data;
        bool directionOk = uint256(returned.payoffDirection) == uint256(initDef.payoffDirection);
        assertTrue(typeOk && dataOk && directionOk);
    }
}

