    }

    function testFuzz_property(
        uint8 payoffTypeSeed,
        uint8 payoffDirectionSeed,
        bytes30 data,
        address oracle
    ) public {
        // payoffType must be a valid enum value: 0, 1, or 2
        uint8 payoffType = payoffTypeSeed % 3;
        // payoffDirection must be 0 (LONG) or 1 (SHORT)
        uint8 payoffDirection = payoffDirectionSeed % 2;
        // oracle must be a contract (oracle provider must return valid versions, so we use a simple mock)
        vm.assume(oracle != address(0) && oracle.code.length > 0);

        // initialize the product
        C.ProductInfo memory info = C.ProductInfo({
            name: "Test",
            symbol: "TST",
            payoffDefinition: PayoffDefinition(
                PayoffDefinitionLib.PayoffType(payoffType),
                PayoffDefinitionLib.PayoffDirection(payoffDirection),
