contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(bytes30 data, uint256 oraclePrice) public {
        // Restrict data to a valid PayoffDefinition for some known payoff type that has a non-trivial transform.
        // We use a passthrough type (e.g., PAYOFF_TYPE_PASSTHROUGH = 0) where transform returns price unchanged,
        // but the bug zeroes data, so transform for other types will differ.
        // To make the bug visible, we need a payoff type whose transform depends on data.
        // PayoffType 1 (BINARY) uses data. Let's use BINARY with direction LONG.
        vm.assume(oraclePrice > 0 && oraclePrice < type(int256).max / 1e18);
        // data must encode a valid BINARY payoff: 32-bit strike, 32-bit notional, 32-bit expiry, etc.
        // We allow any bytes30 and let valid() + transform use it.

        // We'll deploy a helper oracle that returns the given oraclePrice
        MockOracle oracle = new MockOracle();
        oracle.setPrice(int256(oraclePrice) * 1e18);

        // Initialize C with the oracle and the payoff definition
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "test",
            symbol: "TST",
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType.BINARY,
                payoffDirection: PayoffDefinitionLib.PayoffDirection.LONG,
                data: data
            }),
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(0),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });

        // Prank the controller as expected (in real deployment the controller calls initialize, but here we are the deployer)
        // Since UControllerProvider initializer expects msg.sender to be a contract that will become controller()
        // we need a mock controller that returns itself as isProduct etc.
        // Actually C.initialize expects IController(msg.sender). We'll deploy a minimal mock controller.
        MockController controller = new MockController();
        vm.startPrank(address(controller));
        c.initialize(info);
        vm.stopPrank();

        // Now compare the result of payoffDefinition() with the stored definition.
        // Since the reference returns the stored definition, and the bug returns zeroed data,
        // the result of c.payoffDefinition().transform(Fixed18.wrap(int256(oraclePrice)*1e18)) will differ.
        PayoffDefinition memory storedDef = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.BINARY,
            payoffDirection: PayoffDefinitionLib.PayoffDirection.LONG,
            data: data
        });

        // Only run if the original definition is valid.
        vm.assume(storedDef.valid());

        Fixed18 price = Fixed18.wrap(int256(oraclePrice) * 1e18);
        Fixed18 expectedTransformed = storedDef.transform(price);
        Fixed18 actualTransformed = c.payoffDefinition().transform(price);

        assertTrue(expectedTransformed.eq(actualTransformed));
    }
}

