pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(int256 price, bytes30 data) public {
        // price bounded to a reasonable range that avoids overflow in transform
        price = int256(bound(price, -1e30, 1e30));

        // Construct a valid PayoffDefinition with the given data.
        // We choose a standard payoff type and direction that are known to be valid.
        PayoffDefinitionLib.PayoffType pType = PayoffDefinitionLib.PayoffType(1); // PASSTHROUGH
        PayoffDefinitionLib.PayoffDirection pDir = PayoffDefinitionLib.PayoffDirection(0); // NEUTRAL

        PayoffDefinition memory originalDef = PayoffDefinition(pType, pDir, data);

        // Build the ProductInfo struct needed for initialization.
        // We use dummy/zero values for parameters irrelevant to the property.
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "test",
            symbol: "TST",
            payoffDefinition: originalDef,
            oracle: IOracleProvider(address(this)), // mock oracle is this contract
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(0),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });

        // Mock the controller to be this test contract so the initialization passes
        vm.prank(address(this));
        c.initialize(info);

        // Retrieve the stored definition through the getter
        PayoffDefinition memory storedDef = c.payoffDefinition();

        // Create an oracle version using the fuzzed price
        IOracleProvider.OracleVersion memory ov = IOracleProvider.OracleVersion({
            version: 1,
            timestamp: uint256(1000),
            price: Fixed18.wrap(price)
        });

        // Compute the transformed price using the original definition's transform
        Fixed18 expectedPrice = originalDef.transform(ov.price);

        // Compute the transformed price using the stored definition's transform
        Fixed18 actualPrice = storedDef.transform(ov.price);

        // The property: the transform of the stored definition applied to any price
        // must equal the transform of the initially provided definition applied to that price.
        assertTrue(expectedPrice.eq(actualPrice));
    }

    // Minimal mock implementation of IOracleProvider to satisfy initialization checks
    // and allow the test to proceed.
    function currentVersion() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function sync() external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }
    function atVersion(uint256) external pure returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }
    // IController methods required by C's initialization (only basic ones)
    function owner() external view returns (address) {
        return address(this);
    }
    function coordinatorFor(IProduct) external view returns (uint256) {
        return 0;
    }
    function owner(uint256) external view returns (address) {
        return address(this);
    }
    function isProduct(IProduct) external view returns (bool) {
        return true;
    }
}

