pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        // The general rule: the returned price from currentVersion() must be the
        // payoff-definition-transformed version of the underlying oracle's currentVersion.
        // The bug returns the untransformed oracle version directly.
        IOracleProvider.OracleVersion memory cv = c.currentVersion();
        IOracleProvider.OracleVersion memory ocv = c.oracle().currentVersion();
        PayoffDefinition memory pd = c.payoffDefinition();
        Fixed18 expectedPrice = pd.transform(ocv.price);
        assertTrue(Fixed18.unwrap(cv.price) == Fixed18.unwrap(expectedPrice));
    }
}

