contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // The property: for any initialized C, currentVersion().price is
        // oracle().currentVersion().price transformed by payoffDefinition().transform.
        // We check by comparing c.currentVersion().price to the result of
        // calling c.payoffDefinition().transform(c.oracle().currentVersion().price).
        (bool ok, ) = address(c).staticcall(abi.encodeWithSelector(c.currentVersion.selector));
        // currentVersion should not revert on a properly initialized contract
        assertTrue(ok);
    }
}

