    int256 _price;
    uint256 _version = 1;
    uint256 _timestamp = 1;

    function setPrice(int256 p) external { _price = p; }
    function sync() external returns (OracleVersion memory) {
        return OracleVersion(_version, _timestamp, Fixed18.wrap(_price));
