// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address oracle, int256 priceV0, int256 priceCurrent) public {
        // Keep oracle in admissible range: it must be a contract
        vm.assume(oracle != address(0));
        vm.assume(oracle != address(this));
        vm.assume(oracle.code.length > 0);
        // Avoid pathological extremes that would overflow Fixed18 arithmetic during transform
        priceV0 = int256(bound(priceV0, type(int128).min, type(int128).max));
        priceCurrent = int256(bound(priceCurrent, type(int128).min, type(int128).max));

        // Deploy a minimal oracle stub that returns different prices for version 0 and the current version
        OracleStub stub = new OracleStub(priceV0, priceCurrent);
        address stubAddr = address(stub);

        // Create payoff definition that does NOT collapse under transform (use passthrough payoff so transform only depends on raw price)
        // PayoffDefinition: payoffType=PASSTHROUGH (0), payoffDirection=NEUTRAL (0), data=bytes30(0)
        bytes memory payoffDef = abi.encode(uint8(0), uint8(0), bytes30(0));

        // Construct ProductInfo for initialize
        C.ProductInfo memory info;
        info.name = "test";
        info.symbol = "TEST";
        info.oracle = IOracleProvider(stubAddr);
        // PayoffDefinition encoding
        assembly {
            calldatacopy(info, add(payoffDef, 32), 32)
        }
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(1e18);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });

        // Initialize C
        c.initialize(info);

        // Trigger a sync to advance current version to version 1 (version 0 remains available)
        stub.setCurrentVersion(1, priceCurrent);

        // Read currentVersion via both contracts
        // Reference C (P) uses _transform(oracle().currentVersion()) -> uses version 1 raw price then transform
        // Mutant M uses _transform(oracle().atVersion(0)) -> uses version 0 raw price then transform
        // Since transforms are passthrough, P returns priceCurrent, M returns priceV0
        IOracleProvider.OracleVersion memory ver = c.currentVersion();
        Fixed18 returnedPrice = ver.price;

        // The correct behavior: returned price must equal the transformed current version price (priceCurrent)
        assertTrue(Fixed18.unwrap(returnedPrice) == priceCurrent);
    }
}

contract OracleStub is IOracleProvider {
    int256 public priceV0;
    uint256 public currentVersion_;
    mapping(uint256 => int256) public prices;

    constructor(int256 _priceV0, int256 _priceCurrent) {
        priceV0 = _priceV0;
        prices[1] = _priceCurrent;
        currentVersion_ = 1;
    }

    function setCurrentVersion(uint256 version, int256 price) external {
        currentVersion_ = version;
        prices[version] = price;
    }

    function sync() external returns (OracleVersion memory) {
        currentVersion_++;
        prices[currentVersion_] = prices[currentVersion_ - 1];
        return currentVersion();
    }

    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion({
            version: currentVersion_,
            timestamp: block.timestamp,
            price: Fixed18.wrap(prices[currentVersion_])
        });
    }

    function atVersion(uint256 oracleVersion) external view returns (OracleVersion memory) {
        int256 price = oracleVersion == 0 ? priceV0 : prices[oracleVersion];
        return OracleVersion({
            version: oracleVersion,
            timestamp: block.timestamp,
            price: Fixed18.wrap(price)
        });
    }
}
